package com.cie.competition;

import com.cie.competition.common.security.JwtUtil;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

@SpringBootTest @AutoConfigureMockMvc
@EnabledIfEnvironmentVariable(named="RUN_DB_TESTS",matches="true")
@Transactional
class StudentTeamIntegrationTest extends IsolatedDatabaseTest {
 @Autowired JdbcTemplate jdbc; @Autowired MockMvc mvc; @Autowired ObjectMapper json; @Autowired JwtUtil jwt;
 long major,creator,member,other,teacher,admin,competition,second;
 @BeforeEach void fixture(){String tag="preteam_"+UUID.randomUUID();jdbc.update("INSERT INTO sys_major(name) VALUES(?)",tag);major=jdbc.queryForObject("SELECT id FROM sys_major WHERE name=?",Long.class,tag);creator=user("STUDENT");member=user("STUDENT");other=user("STUDENT");teacher=user("TEACHER");admin=user("ADMIN");competition=competition("TEAM");second=competition("TEAM");}
 long user(String role){String name="preteam_"+UUID.randomUUID();jdbc.update("INSERT INTO sys_user(username,password,real_name,role,major_id,status) VALUES(?,'test-only',?,?,?,1)",name,name,role,major);return jdbc.queryForObject("SELECT id FROM sys_user WHERE username=?",Long.class,name);}
 long competition(String type){String name="preteam_"+UUID.randomUUID();jdbc.update("INSERT INTO competition(title,status,competition_type,major_id,max_members,max_teachers,allow_cross_major,publisher_id,registration_start_time,registration_end_time) VALUES(?,'REGISTERING',?,?,3,1,0,?,DATE_SUB(NOW(),INTERVAL 1 DAY),DATE_ADD(NOW(),INTERVAL 1 DAY))",name,type,major,admin);long id=jdbc.queryForObject("SELECT id FROM competition WHERE title=?",Long.class,name);jdbc.update("INSERT INTO guidance_quota(competition_id,teacher_id,quota) VALUES(?,?,2)",id,teacher);return id;}
 String token(long user){return jwt.generateToken(user,"fixture",jdbc.queryForObject("SELECT role FROM sys_user WHERE id=?",String.class,user));}
 JsonNode call(String method,String path,long actor,Object body,int expected)throws Exception{var req=request(org.springframework.http.HttpMethod.valueOf(method),java.net.URI.create("/api"+path)).header("Authorization","Bearer "+token(actor)).contentType("application/json");if(body!=null)req.content(json.writeValueAsBytes(body));var result=json.readTree(mvc.perform(req).andReturn().getResponse().getContentAsByteArray());assertEquals(expected,result.path("code").asInt(),method+" "+path+" "+result.path("message"));return result.path("data");}
 long create(long owner,List<Long> ids)throws Exception{return call("POST","/team",owner,Map.of("name","学生组队","memberIds",ids),200).asLong();}
 void respond(long team,long actor,boolean accept,int expected)throws Exception{call("PUT","/team/"+team+"/response",actor,Map.of("accepted",accept),expected);}
 void captain(long team,long candidate)throws Exception{call("PUT","/team/"+team+"/captain",creator,Map.of("userId",candidate),200);call("PUT","/team/"+team+"/captain/response",candidate,Map.of("accepted",true),200);}
 long ready()throws Exception{long id=create(creator,List.of(member));respond(id,member,true,200);captain(id,member);return id;}
 Map<String,Object> registration(long team,long contest){return Map.of("sourceTeamId",team,"competitionId",contest,"preferredTeacherId",teacher,"teamName","不信任前端名单","memberIds",List.of(other));}
 @Test void studentsCanCreateAndSeeOnlyOwnTeams()throws Exception{long team=create(creator,List.of(member));assertEquals(1,call("GET","/team/mine",creator,null,200).size());assertEquals(1,call("GET","/team/invitations",member,null,200).size());call("GET","/team/"+team,other,null,403);call("POST","/team",teacher,Map.of("name","非法","memberIds",List.of()),403);call("GET","/team/mine",admin,null,403);}
 @Test void captainMustBeAnAcceptedMemberAndConfirmPersonally()throws Exception{long team=create(creator,List.of(member));call("PUT","/team/"+team+"/captain",creator,Map.of("userId",member),400);respond(team,member,true,200);call("PUT","/team/"+team+"/captain",member,Map.of("userId",member),403);call("PUT","/team/"+team+"/captain",creator,Map.of("userId",member),200);call("PUT","/team/"+team+"/captain/response",creator,Map.of("accepted",true),403);call("POST","/registration",member,registration(team,competition),400);call("PUT","/team/"+team+"/captain/response",member,Map.of("accepted",false),200);captain(team,member);assertEquals("READY",call("GET","/team/"+team,member,null,200).path("status").asText());}
 @Test void readyTeamCanRegisterMultipleContestsWithoutDuplicateInvitationsAndKeepsIndependentRosters()throws Exception{long team=ready();call("POST","/registration",creator,registration(team,competition),403);long first=call("POST","/registration",member,registration(team,competition),200).asLong();long next=call("POST","/registration",member,registration(team,second),200).asLong();assertNotEquals(first,next);assertEquals("PENDING",jdbc.queryForObject("SELECT status FROM registration WHERE id=?",String.class,first));assertEquals(team,jdbc.queryForObject("SELECT source_team_id FROM registration WHERE id=?",Long.class,first));assertEquals(Set.of(creator,member),new HashSet<>(jdbc.queryForList("SELECT user_id FROM registration_member WHERE registration_id=? AND active_key=1",Long.class,first)));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM team_invitation WHERE registration_id IN (?,?) AND status='PENDING'",Integer.class,first,next));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM guidance WHERE registration_id IN (?,?)",Integer.class,first,next));call("POST","/team/"+team+"/invitations",creator,Map.of("memberIds",List.of(other)),200);respond(team,other,true,200);assertEquals("FORMING",call("GET","/team/"+team,creator,null,200).path("status").asText());assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM registration_member WHERE registration_id=? AND current_member=1",Integer.class,first));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM registration_member WHERE registration_id=? AND current_member=1",Integer.class,next));}
 @Test void invitationsCanBeRejectedRevokedAndReissuedAndMembersCanLeave()throws Exception{long team=create(creator,List.of(member));respond(team,other,true,403);respond(team,member,false,200);call("POST","/team/"+team+"/invitations",creator,Map.of("memberIds",List.of(member)),200);call("DELETE","/team/"+team+"/members/"+member,creator,null,200);respond(team,member,true,400);call("POST","/team/"+team+"/invitations",creator,Map.of("memberIds",List.of(member)),200);respond(team,member,true,200);call("DELETE","/team/"+team+"/members/"+member,member,null,200);assertTrue(jdbc.queryForObject("SELECT COUNT(*) FROM business_history WHERE biz_type='TEAM' AND biz_id=?",Integer.class,team)>=6);call("DELETE","/team/"+team,creator,null,200);call("POST","/team/"+team+"/invitations",creator,Map.of("memberIds",List.of(other)),400);assertEquals("DISBANDED",jdbc.queryForObject("SELECT status FROM student_team WHERE id=?",String.class,team));}
 @Test void invalidStudentsAndDuplicateInvitationsAreRejected()throws Exception{call("POST","/team",creator,Map.of("name","测试","memberIds",List.of(creator)),400);call("POST","/team",creator,Map.of("name","测试","memberIds",List.of(teacher)),400);call("POST","/team",creator,Map.of("name","测试","memberIds",List.of(member,member)),400);long team=create(creator,List.of(member));jdbc.update("UPDATE sys_user SET status=0 WHERE id=?",member);respond(team,member,true,401);}
 @Test void registrationRevalidatesCompetitionRulesAndQuotaAndRollsBackEverything()throws Exception{long team=ready();jdbc.update("UPDATE sys_user SET major_id=? WHERE id=?",major+999,creator);call("POST","/registration",member,registration(team,competition),400);jdbc.update("UPDATE sys_user SET major_id=? WHERE id=?",major,creator);jdbc.update("UPDATE guidance_quota SET quota=0 WHERE competition_id=?",competition);call("POST","/registration",member,registration(team,competition),400);jdbc.update("UPDATE guidance_quota SET quota=2 WHERE competition_id=?",competition);jdbc.update("UPDATE competition SET registration_end_time=DATE_SUB(NOW(),INTERVAL 1 HOUR) WHERE id=?",competition);call("POST","/registration",member,registration(team,competition),400);long personal=competition("PERSONAL");call("POST","/registration",member,registration(team,personal),400);assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM registration WHERE source_team_id=?",Integer.class,team));}
 @Test void teacherRemainingQuotaReflectsReviewAndCompletionWithoutCountingMembers()throws Exception{long team=ready();assertEquals(2,call("GET","/guidance/teachers?competitionId="+competition,member,null,200).get(0).path("remaining").asInt());long reg=call("POST","/registration",member,registration(team,competition),200).asLong();assertEquals(2,call("GET","/guidance/teachers?competitionId="+competition,member,null,200).get(0).path("remaining").asInt());call("PUT","/registration/"+reg+"/review",admin,Map.of("result","APPROVED","teacherId",teacher),200);assertEquals(1,call("GET","/guidance/teachers?competitionId="+competition,member,null,200).get(0).path("remaining").asInt());long guide=jdbc.queryForObject("SELECT id FROM guidance WHERE registration_id=?",Long.class,reg);call("POST","/guidance/"+guide+"/complete",teacher,null,200);assertEquals(2,call("GET","/guidance/teachers?competitionId="+competition,member,null,200).get(0).path("remaining").asInt());}
 @Test void disabledPreviouslyConfirmedMembersAreRejectedOnRegistration()throws Exception{long team=ready();jdbc.update("UPDATE sys_user SET status=0 WHERE id=?",creator);call("POST","/registration",member,registration(team,competition),400);assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM registration WHERE source_team_id=?",Integer.class,team));}
 @Test @Transactional(propagation=Propagation.NOT_SUPPORTED)
 void concurrentSubmissionsCreateOnlyOneEffectiveTeamRegistration()throws Exception{long team=ready();var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);String auth=token(member);try{Callable<Integer> submit=()->{start.await(10,TimeUnit.SECONDS);return json.readTree(mvc.perform(post("/api/registration").header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsBytes(registration(team,competition)))).andReturn().getResponse().getContentAsByteArray()).path("code").asInt();};var first=pool.submit(submit);var next=pool.submit(submit);start.countDown();assertEquals(Set.of(200,400),Set.of(first.get(20,TimeUnit.SECONDS),next.get(20,TimeUnit.SECONDS)));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM registration WHERE source_team_id=? AND status='PENDING'",Integer.class,team));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM registration_member WHERE competition_id=? AND active_key=1",Integer.class,competition));}finally{pool.shutdownNow();pool.awaitTermination(10,TimeUnit.SECONDS);jdbc.update("DELETE FROM team_invitation WHERE registration_id IN (SELECT id FROM registration WHERE source_team_id=?)",team);jdbc.update("DELETE FROM registration_member WHERE registration_id IN (SELECT id FROM registration WHERE source_team_id=?)",team);jdbc.update("DELETE FROM registration WHERE source_team_id=?",team);jdbc.update("DELETE FROM student_team_member WHERE team_id=?",team);jdbc.update("DELETE FROM student_team WHERE id=?",team);jdbc.update("DELETE FROM guidance_quota WHERE competition_id IN (?,?)",competition,second);jdbc.update("DELETE FROM competition WHERE id IN (?,?)",competition,second);jdbc.update("DELETE FROM sys_user WHERE major_id=?",major);jdbc.update("DELETE FROM sys_major WHERE id=?",major);}}
}
